import {promises as fs} from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {execFile} from 'node:child_process';
import {promisify} from 'node:util';

const run=promisify(execFile);
export const root=path.resolve(import.meta.dirname,'..');
export const bundleRoot=path.join(root,'examples/featured');
const pid=/^p-[a-f0-9]{12}$/;
const vid=/^v-[a-f0-9]{12}$/;
const uuid=/^[a-f0-9-]{36}$/;
const textExtensions=new Set(['.svml','.svs','.svrun','.json','.js','.mjs','.ts','.html','.css','.md','.txt']);
const mediaKinds={'.png':'image','.jpg':'image','.jpeg':'image','.webp':'image','.svg':'image','.gif':'image','.mp4':'video','.mov':'video','.webm':'video','.mp3':'audio','.wav':'audio','.m4a':'audio','.ogg':'audio','.flac':'audio'};
const hash=bytes=>crypto.createHash('sha256').update(bytes).digest('hex');
const readJson=file=>fs.readFile(file,'utf8').then(JSON.parse);
const exists=file=>fs.access(file).then(()=>true,error=>{if(error.code==='ENOENT')return false;throw error;});
async function json(file,value){await fs.mkdir(path.dirname(file),{recursive:true});await fs.writeFile(file,JSON.stringify(value,null,2)+'\n');}
export function safePath(base,relative){if(typeof relative!=='string'||!relative||relative.includes('\\')||path.isAbsolute(relative)||relative.split('/').some(part=>!part||part==='.'||part==='..'))throw Error('素材包路径无效');return path.join(base,relative);}
async function walk(directory){const out=[];if(!await exists(directory))return out;for(const entry of await fs.readdir(directory,{withFileTypes:true})){if(['node_modules','.git','.hypit'].includes(entry.name)||entry.name.startsWith('.'))continue;const file=path.join(directory,entry.name);if(entry.isSymbolicLink())throw Error('素材包源目录不能含符号链接：'+file);if(entry.isDirectory())out.push(...await walk(file));else if(entry.isFile())out.push(file);}return out;}
function assertPublic(text,label){if(/\bsk-[A-Za-z0-9_-]{16,}|Bearer\s+[A-Za-z0-9_.-]{16,}|X-Amz-Signature=|[?&](?:api_key|token|key|signature)=|\/Users\//i.test(text))throw Error('发现未净化的凭据或本机路径：'+label);}
async function copyPublic(source,destination){let bytes=await fs.readFile(source);if(textExtensions.has(path.extname(source))){let text=bytes.toString();text=text.replace(/\/\/ 正式标志来自本机[^\n]+/g,'// 正式标志来自仓库 docs/media/omnicut-mark.svg');assertPublic(text,path.basename(source));bytes=Buffer.from(text);}await fs.mkdir(path.dirname(destination),{recursive:true});await fs.writeFile(destination,bytes);}
function fileReferences(text){return [...text.matchAll(/\b(?:src|source|from)\s*=\s*["']([^"']+)["']/g)].map(match=>match[1]);}
async function closure(directory){const queue=['main.svml','render.svrun','look.svs','package.json'].map(name=>path.join(directory,name));queue.push(...await walk(path.join(directory,'packages')));const seen=new Set();while(queue.length){const file=queue.pop();if(seen.has(file))continue;const relative=path.relative(directory,file);if(relative.startsWith('..')||path.isAbsolute(relative))throw Error('引用超出本工程：'+relative);const stat=await fs.lstat(file);if(!stat.isFile()||stat.isSymbolicLink())throw Error('引用不是普通文件：'+relative);seen.add(file);if(!textExtensions.has(path.extname(file)))continue;const text=await fs.readFile(file,'utf8');for(const reference of ['.svml','.svs','.svrun'].includes(path.extname(file))?fileReferences(text):[]){if(reference.startsWith('/')||reference.startsWith('file:'))throw Error('原生工程引用绝对路径：'+relative);if(reference.startsWith('.'))queue.push(path.resolve(path.dirname(file),reference));}if(path.basename(file)==='package.json'){const pkg=JSON.parse(text);for(const value of Object.values(pkg.dependencies||{})){if(value.startsWith('file:')){const folder=path.resolve(path.dirname(file),value.slice(5));if(!folder.startsWith(directory+path.sep))throw Error('组件引用超出工程');queue.push(...await walk(folder));}}}}return seen;}
function cleanMeta(meta,projectId,videoId){const native={};for(const key of ['author','run','target','output','duration'])if(meta.native?.[key]!==undefined)native[key]=meta.native[key];const clean={id:projectId,projectId,videoId,name:meta.name,brief:meta.name,draft:false,updated:meta.updated,version:meta.version||0,history:[],messages:[],native};if(videoId!=='v-default')clean.parentId='v-default';if(meta.productionPlan)clean.productionPlan={duration:meta.productionPlan.duration,ratio:meta.productionPlan.ratio,route:meta.productionPlan.route,updated:meta.productionPlan.updated,scenes:(meta.productionPlan.scenes||[]).map(scene=>Object.fromEntries(['id','name','start','end','visual','voiceover','route'].filter(key=>scene[key]!==undefined).map(key=>[key,scene[key]])))};assertPublic(JSON.stringify(clean),'项目元数据');return clean;}
const sideKeys=['id','filename','name','kind','duration','videoDuration','width','height','hasAudio','created','poster','vectorFilename','scene','editorialStatus'];
async function addAssetMetadata(source,destination,selected,created){const sidecars=[];for(const file of await fs.readdir(path.join(source,'assets'))){if(file.endsWith('.asset.json'))sidecars.push(await readJson(path.join(source,'assets',file)));}const byDigest=new Map();for(const asset of sidecars){const file=path.join(source,'assets',asset.filename);if(await exists(file)){const digest=hash(await fs.readFile(file));if(!byDigest.has(digest))byDigest.set(digest,asset);}}const handled=new Set();let count=0;for(const file of selected){const relative=path.relative(source,file);if(!relative.startsWith('assets'+path.sep))continue;const kind=mediaKinds[path.extname(file)];if(!kind)continue;let original=sidecars.find(asset=>asset.filename===path.basename(file))||byDigest.get(hash(await fs.readFile(file)));if(!original){const id=hash(Buffer.from(source.split(path.sep).pop()+':'+relative)).slice(0,32).replace(/^(.{8})(.{4})(.{4})(.{4})(.{12})$/,'$1-$2-$3-$4-$5');let info={};try{const {stdout}=await run('ffprobe',['-v','error','-show_streams','-show_format','-of','json',file],{maxBuffer:1e6});const probe=JSON.parse(stdout),video=probe.streams.find(s=>s.codec_type==='video'),audio=probe.streams.find(s=>s.codec_type==='audio');info={duration:kind==='image'?null:Number(probe.format.duration)||null,width:video?.width||null,height:video?.height||null,hasAudio:Boolean(audio)};}catch{}original={id,filename:id+path.extname(file),kind,name:path.basename(file),created,...info};}if(handled.has(original.id))continue;handled.add(original.id);const clean=Object.fromEntries(sideKeys.filter(key=>original[key]!==undefined).map(key=>[key,original[key]]));clean.provenance={provider:'featured',sourcePath:relative.split(path.sep).join('/')};const alias=path.join(destination,'assets',clean.filename);if(!await exists(alias))await copyPublic(file,alias);for(const key of ['poster','vectorFilename']){if(!clean[key])continue;const from=path.join(source,'assets',clean[key]);if(await exists(from))await copyPublic(from,path.join(destination,'assets',clean[key]));else delete clean[key];}assertPublic(JSON.stringify(clean),'素材元数据');await json(path.join(destination,'assets',clean.id+'.asset.json'),clean);count++;}return count;}
function cleanRuntime(original){const runtime={format:'hypit.runtime-local@1',dataRoot:'.hypit/execution',endpoints:{'media.local':{use:'@hypit/provider-media-local',config:{defaultConcurrency:2}},'hyperframes.local':{use:'@hypit/provider-hyperframes-local',config:{workers:2,defaultConcurrency:1}}},bindings:{}};for(const [key,value]of Object.entries(original.bindings||{}))if(['media.local','hyperframes.local'].includes(value))runtime.bindings[key]=value;const source=original.endpoints?.['hyperframes.local']?.config||{};for(const key of ['maxDecodedSourceBytes','maxPendingFrameBytes','quality'])if(source[key]!==undefined)runtime.endpoints['hyperframes.local'].config[key]=source[key];return runtime;}
async function exportFilm(dataRoot,projectId,videoId,meta,destination){let newest;for(const name of await fs.readdir(path.join(dataRoot,'exports'))){if(!uuid.test(name))continue;const file=path.join(dataRoot,'exports',name,'job.json');if(!await exists(file))continue;const job=await readJson(file);if(job.projectId===projectId&&(job.videoId||'v-default')===videoId&&job.status==='done'&&(!newest||job.created>newest.created))newest=job;}if(!newest)throw Error('置顶视频没有成片：'+projectId+'/'+videoId);const relative='exports/'+newest.id,source=path.join(dataRoot,relative),target=path.join(destination,relative);await fs.mkdir(target,{recursive:true});await fs.copyFile(path.join(source,'final.mp4'),path.join(target,'final.mp4'));for(const [file,share,width]of [['poster.jpg',.15,640],['cover.jpg',.35,960]]){if(await exists(path.join(source,file)))await fs.copyFile(path.join(source,file),path.join(target,file));else await run('ffmpeg',['-hide_banner','-loglevel','error','-ss',String(Number(newest.duration)*share),'-i',path.join(target,'final.mp4'),'-frames:v','1','-vf','scale='+width+':-2','-q:v','3','-y',path.join(target,file)],{timeout:20000});}const clean={id:newest.id,projectId,videoId,name:newest.name||meta.name+'·成片',created:newest.created,status:'done',duration:newest.duration,output:newest.output||meta.native.output,fileSize:(await fs.stat(path.join(target,'final.mp4'))).size,revision:newest.revision,runtimeStopped:true};await json(path.join(target,'job.json'),clean);return {id:clean.id,revision:clean.revision,directory:relative,file:relative+'/final.mp4',poster:relative+'/poster.jpg',cover:relative+'/cover.jpg'};}
export async function packFeatured({dataRoot=path.join(root,'data'),destination=bundleRoot}={}){const ids=(await readJson(path.join(dataRoot,'project-pins.json'))).ids;if(!Array.isArray(ids)||!ids.length||ids.some(id=>!pid.test(id)))throw Error('没有有效的置顶项目');await fs.mkdir(destination,{recursive:true});if(await exists(path.join(destination,'manifest.json')))throw Error('素材包已存在，请先检查再移走旧 examples/featured；不自动覆盖');const projects=[];for(const [order,id]of ids.entries()){const base=path.join(dataRoot,'projects',id),project={id,name:(await readJson(path.join(base,'project.json'))).name,pinned:order+1,videos:[]};const variants=(await fs.readdir(path.join(base,'productions')).catch(error=>{if(error.code==='ENOENT')return [];throw error;})).filter(name=>vid.test(name));for(const videoId of ['v-default',...variants]){const relative='projects/'+id+(videoId==='v-default'?'':'/productions/'+videoId),source=path.join(dataRoot,relative),target=path.join(destination,relative),meta=cleanMeta(await readJson(path.join(source,'project.json')),id,videoId),files=await closure(source);for(const file of files)await copyPublic(file,path.join(target,path.relative(source,file)));await json(path.join(target,'project.json'),meta);await json(path.join(target,'hypit.runtime.json'),cleanRuntime(await readJson(path.join(source,'hypit.runtime.json'))));for(const name of ['OFL-NotoSansCJK.txt','NOTICE.txt'])await copyPublic(path.join(root,'fonts',name),path.join(target,'assets',name));const assets=await addAssetMetadata(source,target,files,meta.updated);const sourceText=await fs.readFile(path.join(target,'main.svml'),'utf8'),style=await fs.readFile(path.join(target,'look.svs'),'utf8'),sourceRevision=String(meta.version)+':'+hash(Buffer.from(sourceText+'\0'+style)).slice(0,16);const film=await exportFilm(dataRoot,id,videoId,meta,destination);project.videos.push({id:videoId,name:meta.name,directory:relative,duration:meta.native.duration,output:meta.native.output,assetCount:assets,sourceRevision,sourceMatchesExport:sourceRevision===film.revision,export:film});}projects.push(project);}await copyPublic(path.join(root,'fonts/OFL-NotoSansCJK.txt'),path.join(destination,'licenses/OFL-NotoSansCJK.txt'));const all=await walk(destination),entries=[];for(const file of all){if(['manifest.json','verification.json'].includes(path.basename(file)))continue;const bytes=await fs.readFile(file);entries.push({path:path.relative(destination,file).split(path.sep).join('/'),size:bytes.length,sha256:hash(bytes)});}entries.sort((a,b)=>a.path.localeCompare(b.path));const unique=new Map(entries.map(entry=>[entry.sha256,entry.size]));const manifest={format:'omnicut.featured@1',generatedAt:new Date().toISOString(),projects,files:entries,summary:{projects:projects.length,videos:projects.reduce((sum,p)=>sum+p.videos.length,0),files:entries.length,totalBytes:entries.reduce((sum,e)=>sum+e.size,0),uniqueBytes:[...unique.values()].reduce((sum,size)=>sum+size,0),maxFileBytes:Math.max(...entries.map(e=>e.size))}};await json(path.join(destination,'manifest.json'),manifest);const report=await verifyFeatured(destination);await json(path.join(destination,'verification.json'),report);return manifest;}
export async function verifyFeatured(directory=bundleRoot){const manifest=await readJson(path.join(directory,'manifest.json'));if(manifest.format!=='omnicut.featured@1'||!Array.isArray(manifest.files)||!Array.isArray(manifest.projects))throw Error('未知的展示素材包');let bytes=0;for(const entry of manifest.files){const file=safePath(directory,entry.path),stat=await fs.lstat(file);if(!stat.isFile()||stat.isSymbolicLink())throw Error('素材包不是普通文件：'+entry.path);const data=await fs.readFile(file);if(data.length!==entry.size||hash(data)!==entry.sha256)throw Error('素材包文件已变更：'+entry.path);bytes+=data.length;if(textExtensions.has(path.extname(file)))assertPublic(data.toString(),entry.path);}const references=[];for(const project of manifest.projects){if(!pid.test(project.id))throw Error('项目编号无效');for(const video of project.videos){if(video.id!=='v-default'&&!vid.test(video.id))throw Error('视频编号无效');const base=safePath(directory,video.directory);const files=await closure(base);for(const file of files)if(['.svml','.svs','.svrun'].includes(path.extname(file)))for(const ref of fileReferences(await fs.readFile(file,'utf8')))if(ref.startsWith('.'))references.push({file:path.relative(directory,file).split(path.sep).join('/'),reference:ref});const meta=await readJson(path.join(base,'project.json'));if(meta.messages.length||meta.history.length)throw Error('公开包不得携带会话或历史');await fs.access(safePath(directory,video.export.file));}}return {format:'omnicut.featured-verification@1',checkedAt:new Date().toISOString(),projects:manifest.projects.length,videos:manifest.summary.videos,files:manifest.files.length,referenceCount:references.length,totalBytes:bytes,missingReferences:[],absolutePaths:[],credentials:[],privateConversations:0,references};}
async function linkComponents(directory){for(const file of await walk(directory)){if(path.basename(file)!=='package.json')continue;const pkg=await readJson(file),base=path.dirname(file);for(const [name,version]of Object.entries(pkg.dependencies||{})){if(!version.startsWith('file:'))continue;if(!/^(@[a-z0-9_-]+\/)?[a-z0-9_.-]+$/i.test(name))throw Error('组件包名无效');const target=path.resolve(base,version.slice(5));if(!target.startsWith(directory+path.sep)||!await exists(target))throw Error('组件必须包含在展示工程内');const link=path.join(base,'node_modules',name);await fs.mkdir(path.dirname(link),{recursive:true});await fs.symlink(path.relative(path.dirname(link),target),link,'dir');}}}
export async function importFeatured({directory=bundleRoot,dataRoot=path.join(root,'data')}={}){await verifyFeatured(directory);const manifest=await readJson(path.join(directory,'manifest.json'));dataRoot=path.resolve(dataRoot);await fs.mkdir(dataRoot,{recursive:true});for(const name of ['projects','exports']){const file=path.join(dataRoot,name);if(await exists(file)){const stat=await fs.lstat(file);if(!stat.isDirectory()||stat.isSymbolicLink())throw Error('目标数据目录不能含外部链接：'+name);}}const plans=manifest.projects.flatMap(project=>[{from:'projects/'+project.id,to:'projects/'+project.id},...project.videos.map(video=>({from:video.export.directory,to:video.export.directory}))]);for(const entry of plans)if(await exists(safePath(dataRoot,entry.to)))throw Error('已有项目或成片，拒绝覆盖：'+entry.to);let pins={ids:[]};if(await exists(path.join(dataRoot,'project-pins.json')))pins=await readJson(path.join(dataRoot,'project-pins.json'));if(!Array.isArray(pins.ids))throw Error('现有置顶记录无效');const stage=path.join(dataRoot,'.featured-import-'+crypto.randomUUID()),moved=[];await fs.mkdir(stage,{recursive:true});try{for(const entry of plans)for(const file of manifest.files.filter(file=>file.path.startsWith(entry.from+'/'))){const destination=safePath(stage,file.path);await fs.mkdir(path.dirname(destination),{recursive:true});await fs.copyFile(safePath(directory,file.path),destination);}for(const project of manifest.projects)await linkComponents(path.join(stage,'projects',project.id));for(const entry of plans){const target=safePath(dataRoot,entry.to);await fs.mkdir(path.dirname(target),{recursive:true});await fs.rename(safePath(stage,entry.to),target);moved.push(target);}const temp=path.join(dataRoot,'project-pins.'+crypto.randomUUID()+'.tmp');await json(temp,{ids:[...pins.ids,...manifest.projects.map(p=>p.id).filter(id=>!pins.ids.includes(id))]});await fs.rename(temp,path.join(dataRoot,'project-pins.json'));return {projects:manifest.projects.length,videos:manifest.summary.videos,dataRoot};}catch(error){for(const file of moved)await fs.rm(file,{recursive:true,force:true});throw error;}finally{await fs.rm(stage,{recursive:true,force:true});}}
